insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('be97567c-2b28-451e-b5b3-b150f2a74260', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Modern Theater Historiography and Research Methods', 'Theater History II asks students to track a rapidly expanding modern field: industrialization, empire, realism, modernism, mass media, civil rights, feminism, globalization, and digital culture all reshape theater. This opening topic trains students to interpret modern theater through evidence, institutions, and historiographic debate.', 0),
  ('4a9ebc4d-da7d-44a2-a173-6d685aa0aaa3', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'be97567c-2b28-451e-b5b3-b150f2a74260', 'subtopic'::public.curated_course_node_type, 'Modernity and performance evidence', 'Why learn it: Students learn how modern theater leaves different traces than earlier theater: photographs, prompt books, reviews, manifestos, video, oral histories, and institutional records.', 0),
  ('301798e0-6d80-4df0-9558-262454ae43b0', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '4a9ebc4d-da7d-44a2-a173-6d685aa0aaa3', 'concept'::public.curated_course_node_type, 'Reviews and criticism', null, 0),
  ('46771f05-ada3-478f-b2fe-c6bb0ea5ad53', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '4a9ebc4d-da7d-44a2-a173-6d685aa0aaa3', 'concept'::public.curated_course_node_type, 'Production photographs', null, 1),
  ('b6e78fe7-02f3-4e3b-9fdc-31d535b7feb1', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '4a9ebc4d-da7d-44a2-a173-6d685aa0aaa3', 'concept'::public.curated_course_node_type, 'Prompt books and programs', null, 2),
  ('b10b02cf-fc0a-4398-b18a-ea997f6767d7', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '4a9ebc4d-da7d-44a2-a173-6d685aa0aaa3', 'concept'::public.curated_course_node_type, 'Recorded performance and archives', null, 3),
  ('90de379e-1404-4824-bf05-4b5112421ff8', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'be97567c-2b28-451e-b5b3-b150f2a74260', 'subtopic'::public.curated_course_node_type, 'Canon revision', 'Why learn it: The point is to ask why some artists became central to theater history while others were excluded by race, gender, class, language, geography, or access to publication.', 1),
  ('5b3b35ac-b820-492f-bb12-cc6f613dfe70', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '90de379e-1404-4824-bf05-4b5112421ff8', 'concept'::public.curated_course_node_type, 'Commercial success vs. preservation', null, 0),
  ('6791f37d-be66-4028-92e1-a569ec5a55d6', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '90de379e-1404-4824-bf05-4b5112421ff8', 'concept'::public.curated_course_node_type, 'Translation and circulation', null, 1),
  ('14ad020c-4a75-4142-8e66-7718587b8024', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '90de379e-1404-4824-bf05-4b5112421ff8', 'concept'::public.curated_course_node_type, 'University anthologies', null, 2),
  ('62d9aced-0061-4c25-89a0-88f5b59fa300', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '90de379e-1404-4824-bf05-4b5112421ff8', 'concept'::public.curated_course_node_type, 'Archives and erasure', null, 3),
  ('9a462e06-c8bf-4cca-97f2-afa56ea0ab0c', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'be97567c-2b28-451e-b5b3-b150f2a74260', 'subtopic'::public.curated_course_node_type, 'Research and citation practice', 'Why learn it: Students build habits for historical argument, source evaluation, and ethical quotation of living or recently living communities.', 2),
  ('acd98bb0-306e-4130-8bb4-dcf1bf6cf928', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9a462e06-c8bf-4cca-97f2-afa56ea0ab0c', 'concept'::public.curated_course_node_type, 'Primary/secondary distinction', null, 0),
  ('29ebd0ec-0476-4883-bd1f-580d24b980bc', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9a462e06-c8bf-4cca-97f2-afa56ea0ab0c', 'concept'::public.curated_course_node_type, 'Annotated bibliography', null, 1),
  ('3660c544-00c9-4705-9353-f7356e6339fd', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9a462e06-c8bf-4cca-97f2-afa56ea0ab0c', 'concept'::public.curated_course_node_type, 'Oral history ethics', null, 2),
  ('e81e8db2-a0f3-4ff0-ae6b-89703d6d9682', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9a462e06-c8bf-4cca-97f2-afa56ea0ab0c', 'concept'::public.curated_course_node_type, 'Digital archive literacy', null, 3),
  ('d5d15c1a-c76e-4e0f-8dc8-63621e7e4345', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Romanticism and Melodrama', 'Romanticism and melodrama introduce the 19th century as an age of emotion, spectacle, nationalism, popular entertainment, and changing audiences. Students see how theatrical taste shifts away from neoclassical restraint toward heightened feeling and visual effect.', 1),
  ('eea25bb8-cbdb-43d6-b8d0-bfeb894b60df', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd5d15c1a-c76e-4e0f-8dc8-63621e7e4345', 'subtopic'::public.curated_course_node_type, 'Romantic revolt', 'Why learn it: Students learn how Romantic theater challenged rules of genre, decorum, and classical hierarchy.', 0),
  ('2a4d559f-a28b-4092-af61-d8674fa75d45', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'eea25bb8-cbdb-43d6-b8d0-bfeb894b60df', 'concept'::public.curated_course_node_type, 'Victor Hugo', null, 0),
  ('aa378372-3db8-41dc-8fe9-e01ed2df51d4', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'eea25bb8-cbdb-43d6-b8d0-bfeb894b60df', 'concept'::public.curated_course_node_type, 'Prefaces and manifestos', null, 1),
  ('bdb85f39-e943-46b2-a719-a0f797bb3e70', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'eea25bb8-cbdb-43d6-b8d0-bfeb894b60df', 'concept'::public.curated_course_node_type, 'The grotesque and sublime', null, 2),
  ('53526a21-ca59-4bdf-942d-17339b192fc3', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'eea25bb8-cbdb-43d6-b8d0-bfeb894b60df', 'concept'::public.curated_course_node_type, 'National identity', null, 3),
  ('20c8309c-66c5-4f1c-bdcc-da5e9a4e8832', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd5d15c1a-c76e-4e0f-8dc8-63621e7e4345', 'subtopic'::public.curated_course_node_type, 'Melodrama as popular form', 'Why learn it: Students study melodrama as a major theatrical language of morality, sensation, music, and spectacle.', 1),
  ('29ca7404-bf0a-4f06-960b-6c604fd123ec', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '20c8309c-66c5-4f1c-bdcc-da5e9a4e8832', 'concept'::public.curated_course_node_type, 'Villains and victims', null, 0),
  ('2272013e-a018-472b-83a4-491c01444d3f', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '20c8309c-66c5-4f1c-bdcc-da5e9a4e8832', 'concept'::public.curated_course_node_type, 'Music underscoring', null, 1),
  ('a3a2e149-0a61-4f69-a64a-c6997c2fb07d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '20c8309c-66c5-4f1c-bdcc-da5e9a4e8832', 'concept'::public.curated_course_node_type, 'Sensation scenes', null, 2),
  ('bed637ca-9e71-4d2f-b861-8aa34037e053', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '20c8309c-66c5-4f1c-bdcc-da5e9a4e8832', 'concept'::public.curated_course_node_type, 'Moral legibility', null, 3),
  ('c001c41c-5e28-4e20-b145-d61d4a1f4eac', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd5d15c1a-c76e-4e0f-8dc8-63621e7e4345', 'subtopic'::public.curated_course_node_type, '19th-century theater industry', 'Why learn it: Students connect dramatic form to urbanization, touring, star actors, patents, censorship, and commercial management.', 2),
  ('41017f65-cb2a-4151-8b11-2aac77116e28', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'c001c41c-5e28-4e20-b145-d61d4a1f4eac', 'concept'::public.curated_course_node_type, 'Boulevard theaters', null, 0),
  ('1ab48a5e-a727-4799-9ccc-e70931c76721', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'c001c41c-5e28-4e20-b145-d61d4a1f4eac', 'concept'::public.curated_course_node_type, 'Stock companies', null, 1),
  ('a118771c-09f5-42fe-9d28-fbae36859059', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'c001c41c-5e28-4e20-b145-d61d4a1f4eac', 'concept'::public.curated_course_node_type, 'Star system', null, 2),
  ('90838c6a-4b49-405a-8401-b2d23a9bbedd', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'c001c41c-5e28-4e20-b145-d61d4a1f4eac', 'concept'::public.curated_course_node_type, 'Gaslight and scenic effects', null, 3),
  ('414db79d-3dc8-40ba-82fd-5fbda3d68ace', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Realism and Naturalism', 'Realism and naturalism reshape modern drama by putting ordinary life, social systems, psychology, and environment at the center of theatrical representation. Students learn why this shift became foundational for modern acting, directing, design, and dramaturgy.', 2),
  ('37de8cba-77b4-4254-b221-7c76d78d1bf3', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '414db79d-3dc8-40ba-82fd-5fbda3d68ace', 'subtopic'::public.curated_course_node_type, 'Realist dramaturgy', 'Why learn it: Students analyze how subtext, social conflict, prose dialogue, and domestic settings produce modern dramatic tension.', 0),
  ('3a702f18-4e1c-4dbd-9f32-59893a63dc84', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '37de8cba-77b4-4254-b221-7c76d78d1bf3', 'concept'::public.curated_course_node_type, 'Henrik Ibsen', null, 0),
  ('fdbf8563-4fae-43be-b6bd-1dd953fc7f54', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '37de8cba-77b4-4254-b221-7c76d78d1bf3', 'concept'::public.curated_course_node_type, 'Anton Chekhov', null, 1),
  ('2640ee31-ebd4-404c-8187-8c5aa2acfbfd', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '37de8cba-77b4-4254-b221-7c76d78d1bf3', 'concept'::public.curated_course_node_type, 'The well-made play', null, 2),
  ('cda82396-ffd2-4565-9966-698ca7f2630d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '37de8cba-77b4-4254-b221-7c76d78d1bf3', 'concept'::public.curated_course_node_type, 'Subtext and silence', null, 3),
  ('c815f1b8-227f-4691-84ea-ce7b7569f2f5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '414db79d-3dc8-40ba-82fd-5fbda3d68ace', 'subtopic'::public.curated_course_node_type, 'Naturalism and environment', 'Why learn it: Students learn how heredity, class, labor, and material conditions become dramatic forces.', 1),
  ('7eeba159-5883-428d-a363-02faea6caa8c', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'c815f1b8-227f-4691-84ea-ce7b7569f2f5', 'concept'::public.curated_course_node_type, 'Emile Zola', null, 0);
