  ('a3346be9-3819-4354-9b07-2b6546ac6727', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '22e21c09-4730-4893-ad64-381af5f9de07', 'concept'::public.curated_course_node_type, 'Ensemble practice', null, 2),
  ('d979fbd2-fc48-4b33-bf10-569813060ffb', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '22e21c09-4730-4893-ad64-381af5f9de07', 'concept'::public.curated_course_node_type, 'Given circumstances', null, 3),
  ('27021253-30dd-4d0d-82f8-0ff0d8aa152c', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Symbolism and the Avant-Garde', 'Symbolism and the avant-garde show artists rejecting literal realism in favor of dream, ritual, abstraction, manifesto, shock, and anti-bourgeois experiment. Students learn that modern theater develops through competing ideas of truth.', 3),
  ('7652c268-05e5-4ea6-97a5-bc93d7d3d3d4', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '27021253-30dd-4d0d-82f8-0ff0d8aa152c', 'subtopic'::public.curated_course_node_type, 'Symbolist theater', 'Why learn it: Students examine atmosphere, suggestion, music, color, and spiritual mystery as alternatives to realist detail.', 0),
  ('d3d4ffdb-e8be-4278-b78c-8e74ffdb4585', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '7652c268-05e5-4ea6-97a5-bc93d7d3d3d4', 'concept'::public.curated_course_node_type, 'Maeterlinck', null, 0),
