  ('2a4c2836-fccd-495b-a071-d3fc5cc199e8', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '7652c268-05e5-4ea6-97a5-bc93d7d3d3d4', 'concept'::public.curated_course_node_type, 'Dream logic', null, 2),
  ('2425b3fd-79c3-44f0-b54a-49cc0ed86df2', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '7652c268-05e5-4ea6-97a5-bc93d7d3d3d4', 'concept'::public.curated_course_node_type, 'Anti-naturalist staging', null, 3),
  ('60745087-f001-4e99-87ca-fdb7f2f90580', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '27021253-30dd-4d0d-82f8-0ff0d8aa152c', 'subtopic'::public.curated_course_node_type, 'Futurism, Dada, and Surrealism', 'Why learn it: Students study performance as provocation, speed, collage, nonsense, anti-war protest, and unconscious expression.', 1),
  ('4f688539-fc0a-494c-bcaa-699055ecbe19', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '60745087-f001-4e99-87ca-fdb7f2f90580', 'concept'::public.curated_course_node_type, 'Marinetti', null, 0),
  ('78937b28-46a7-477a-bfc9-4e8e75b15a6b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '60745087-f001-4e99-87ca-fdb7f2f90580', 'concept'::public.curated_course_node_type, 'Cabaret Voltaire', null, 1),
  ('bdfefb57-84f9-4cd8-8fad-4693785eac3b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '60745087-f001-4e99-87ca-fdb7f2f90580', 'concept'::public.curated_course_node_type, 'Automatic writing', null, 2),
  ('bc7e331d-0283-4d46-93a6-3b101d54cc63', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '60745087-f001-4e99-87ca-fdb7f2f90580', 'concept'::public.curated_course_node_type, 'Manifesto performance', null, 3),
  ('9ea2835f-7883-4a1d-bd5d-1411b04a5c8b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '27021253-30dd-4d0d-82f8-0ff0d8aa152c', 'subtopic'::public.curated_course_node_type, 'Avant-garde scenography', 'Why learn it: Students connect visual abstraction to new theories of stage space, light, movement, and audience perception.', 2),
  ('94141730-c1bf-4d42-b71a-ef33a02d0fa2', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9ea2835f-7883-4a1d-bd5d-1411b04a5c8b', 'concept'::public.curated_course_node_type, 'Adolphe Appia', null, 0),
  ('8dfb22f0-8ab9-4f8e-91c0-d2de75b8ba85', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9ea2835f-7883-4a1d-bd5d-1411b04a5c8b', 'concept'::public.curated_course_node_type, 'Edward Gordon Craig', null, 1),
  ('9936b526-7c48-40f4-a317-e4cbc8fc4580', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9ea2835f-7883-4a1d-bd5d-1411b04a5c8b', 'concept'::public.curated_course_node_type, 'Plastic space', null, 2),
  ('2252dd08-5b6b-45bf-b662-5f810144df5d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9ea2835f-7883-4a1d-bd5d-1411b04a5c8b', 'concept'::public.curated_course_node_type, 'Performer as image', null, 3),
  ('92226173-7d3c-4861-892a-447e397361f6', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Expressionism', 'Expressionism turns theater inward and outward at once: distorted worlds reveal psychic crisis, social alienation, industrial pressure, and political anxiety. Students learn how form can stage subjective experience.', 4),
  ('08d65372-125d-4510-9d53-9e8c39366840', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '92226173-7d3c-4861-892a-447e397361f6', 'subtopic'::public.curated_course_node_type, 'Expressionist dramaturgy', 'Why learn it: Students identify episodic structure, archetypal characters, distorted dialogue, and nightmare logic.', 0),
  ('b07a7ff9-3bca-430b-8d98-7aef004b651e', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '08d65372-125d-4510-9d53-9e8c39366840', 'concept'::public.curated_course_node_type, 'Stationsdrama', null, 0),
  ('30181fdf-f341-4dba-8ee0-68f6e37f3d89', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '08d65372-125d-4510-9d53-9e8c39366840', 'concept'::public.curated_course_node_type, 'Archetypes', null, 1),
  ('52f1d118-b9cd-454c-91b7-dc4986f1d2d2', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '08d65372-125d-4510-9d53-9e8c39366840', 'concept'::public.curated_course_node_type, 'Monologue and outcry', null, 2),
  ('bcb3695a-ba3e-48cb-8de0-8849b26994f1', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '08d65372-125d-4510-9d53-9e8c39366840', 'concept'::public.curated_course_node_type, 'Fragmented scenes', null, 3),
  ('9db1e1fd-197e-4eb9-a35a-7869beb717d3', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '92226173-7d3c-4861-892a-447e397361f6', 'subtopic'::public.curated_course_node_type, 'Design and performance style', 'Why learn it: Students learn how light, shadow, gesture, makeup, sound, and angular space externalize inner states.', 1),
  ('c5b568aa-1abb-4f91-936f-3fafe054569b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9db1e1fd-197e-4eb9-a35a-7869beb717d3', 'concept'::public.curated_course_node_type, 'Distortion', null, 0),
  ('f4f78a55-7262-441b-9383-40cee82ae159', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9db1e1fd-197e-4eb9-a35a-7869beb717d3', 'concept'::public.curated_course_node_type, 'Chiaroscuro', null, 1),
  ('f59e801e-b2e5-4c60-b2b9-e292b379f61b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9db1e1fd-197e-4eb9-a35a-7869beb717d3', 'concept'::public.curated_course_node_type, 'Stylized movement', null, 2),
  ('495552eb-e35d-43e6-9a99-a90ecb6d79bf', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '9db1e1fd-197e-4eb9-a35a-7869beb717d3', 'concept'::public.curated_course_node_type, 'Anti-realistic sound', null, 3),
  ('ad0850a8-75fa-4209-a372-d5c413ca09e1', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '92226173-7d3c-4861-892a-447e397361f6', 'subtopic'::public.curated_course_node_type, 'Social critique', 'Why learn it: Students connect expressionism to war, industrial labor, bureaucracy, family power, and modern alienation.', 2),
  ('6a3b86f1-7358-4183-8a22-b476b9ce9112', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'ad0850a8-75fa-4209-a372-d5c413ca09e1', 'concept'::public.curated_course_node_type, 'Georg Kaiser', null, 0),
  ('7b160e1b-ee6d-42f3-ba46-63a6e6eef28d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'ad0850a8-75fa-4209-a372-d5c413ca09e1', 'concept'::public.curated_course_node_type, 'Ernst Toller', null, 1),
  ('e5960b60-eb1f-422f-9e21-92cde4e450e5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'ad0850a8-75fa-4209-a372-d5c413ca09e1', 'concept'::public.curated_course_node_type, 'Machine age', null, 2),
