insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('0865b672-2553-4cf1-a98e-0620da4da621', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Epic Theater and Brecht', 'Epic theater asks students to understand theater as a tool for historical analysis rather than emotional absorption alone. Brecht becomes a gateway into politics, spectatorship, performance theory, and anti-illusionist staging.', 5),
  ('1ebd285d-2f8c-4916-94cd-e14bb84b2b87', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '0865b672-2553-4cf1-a98e-0620da4da621', 'subtopic'::public.curated_course_node_type, 'Alienation and critical spectatorship', 'Why learn it: Students learn how theater can interrupt identification and invite analysis.', 0),
  ('3f7031d4-48f8-4cf2-bbe8-9bd6a599b62d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '1ebd285d-2f8c-4916-94cd-e14bb84b2b87', 'concept'::public.curated_course_node_type, 'Verfremdungseffekt', null, 0),
