  ('43c3312c-1bb9-4158-981b-6241840cd2eb', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '1ebd285d-2f8c-4916-94cd-e14bb84b2b87', 'concept'::public.curated_course_node_type, 'Placards', null, 2),
  ('ab49b400-ea47-49af-bfc0-11e9f60cfae3', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '1ebd285d-2f8c-4916-94cd-e14bb84b2b87', 'concept'::public.curated_course_node_type, 'Visible mechanics', null, 3),
  ('e2acae15-200f-4739-8cc5-74e64ec1e982', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '0865b672-2553-4cf1-a98e-0620da4da621', 'subtopic'::public.curated_course_node_type, 'Historification and dialectics', 'Why learn it: Students study how epic theater frames social arrangements as changeable rather than natural.', 1),
  ('f8aa2466-7d7d-467f-9aff-afbd04bb7800', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e2acae15-200f-4739-8cc5-74e64ec1e982', 'concept'::public.curated_course_node_type, 'Gestus', null, 0),
  ('c817dc09-feef-49eb-be3b-2bd892e8ff34', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e2acae15-200f-4739-8cc5-74e64ec1e982', 'concept'::public.curated_course_node_type, 'Contradiction', null, 1),
  ('f256a14b-fbbf-42b7-871f-eaf004cd6e39', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e2acae15-200f-4739-8cc5-74e64ec1e982', 'concept'::public.curated_course_node_type, 'Scene titles', null, 2),
  ('f96652a8-b169-45a1-97d0-d584dc43ee89', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e2acae15-200f-4739-8cc5-74e64ec1e982', 'concept'::public.curated_course_node_type, 'Narrative interruption', null, 3),
  ('e6d0e77e-43c8-4c78-ba14-1cc46103e276', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '0865b672-2553-4cf1-a98e-0620da4da621', 'subtopic'::public.curated_course_node_type, 'Brechtian legacy', 'Why learn it: Students trace epic techniques into documentary theater, political theater, devised performance, and contemporary staging.', 2),
  ('e960da43-6d37-4cfd-8113-a7b38d60ffc5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e6d0e77e-43c8-4c78-ba14-1cc46103e276', 'concept'::public.curated_course_node_type, 'Mother Courage', null, 0),
  ('be3abce9-28ca-4ec7-a374-a8d0816c4ce0', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e6d0e77e-43c8-4c78-ba14-1cc46103e276', 'concept'::public.curated_course_node_type, 'The Good Person of Szechwan', null, 1),
  ('d98d3953-b5b3-436e-aa1e-7299199c115b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e6d0e77e-43c8-4c78-ba14-1cc46103e276', 'concept'::public.curated_course_node_type, 'Political cabaret', null, 2),
  ('7d2bd3f5-8bc9-487b-b579-8b850f9fecba', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e6d0e77e-43c8-4c78-ba14-1cc46103e276', 'concept'::public.curated_course_node_type, 'Documentary forms', null, 3),
  ('f5c99ffb-d78a-4758-be1d-e658bea3fb78', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Absurdism and Postwar Theater', 'Absurdism responds to war, existential crisis, fractured communication, and the collapse of stable meaning. Students learn how repetition, silence, circular action, and comic despair create a postwar theatrical language.', 6),
  ('07aef9b6-6641-413f-b414-a797d4543f95', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'f5c99ffb-d78a-4758-be1d-e658bea3fb78', 'subtopic'::public.curated_course_node_type, 'Theater of the Absurd', 'Why learn it: Students analyze how Beckett, Ionesco, Genet, and others challenge plot, character, language, and certainty.', 0),
  ('229d07e4-96c2-4182-9245-38d77f1a4c13', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '07aef9b6-6641-413f-b414-a797d4543f95', 'concept'::public.curated_course_node_type, 'Samuel Beckett', null, 0),
  ('f113fcde-477b-48ea-8980-f65c4bfcb892', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '07aef9b6-6641-413f-b414-a797d4543f95', 'concept'::public.curated_course_node_type, 'Eugene Ionesco', null, 1),
  ('2600e0e8-01a0-4dde-aa2d-86679d72b79c', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '07aef9b6-6641-413f-b414-a797d4543f95', 'concept'::public.curated_course_node_type, 'Jean Genet', null, 2),
  ('6950b4c7-5bc5-421f-8c4b-c4c40e3a9d11', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '07aef9b6-6641-413f-b414-a797d4543f95', 'concept'::public.curated_course_node_type, 'Circular structure', null, 3),
  ('2f6e0b7f-57a8-4177-b209-5c8bee7834a9', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'f5c99ffb-d78a-4758-be1d-e658bea3fb78', 'subtopic'::public.curated_course_node_type, 'Language breakdown', 'Why learn it: Students learn how failed communication becomes dramatic action.', 1),
  ('9ec65fc3-a44a-46e1-b3b3-fc3846584210', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2f6e0b7f-57a8-4177-b209-5c8bee7834a9', 'concept'::public.curated_course_node_type, 'Cliche', null, 0),
  ('692322b5-5c64-45fc-b845-cafa29afa5d2', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2f6e0b7f-57a8-4177-b209-5c8bee7834a9', 'concept'::public.curated_course_node_type, 'Repetition', null, 1),
  ('321b595a-0fcf-48db-a6c6-e1150972b7c6', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2f6e0b7f-57a8-4177-b209-5c8bee7834a9', 'concept'::public.curated_course_node_type, 'Silence', null, 2),
  ('39a4fd37-d5fb-4d7f-b561-2a834d3ac329', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2f6e0b7f-57a8-4177-b209-5c8bee7834a9', 'concept'::public.curated_course_node_type, 'Nonsense logic', null, 3),
  ('e31cc552-be42-4560-8f2a-80c7e7723462', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'f5c99ffb-d78a-4758-be1d-e658bea3fb78', 'subtopic'::public.curated_course_node_type, 'Postwar context', 'Why learn it: Students connect absurdism to World War II, existentialism, displacement, bureaucracy, and modern anxiety.', 2),
  ('b77d7f63-2463-499f-a147-a7291b23800e', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e31cc552-be42-4560-8f2a-80c7e7723462', 'concept'::public.curated_course_node_type, 'Existential philosophy', null, 0),
  ('fa596d04-b434-4c2d-b0f1-95676924b089', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e31cc552-be42-4560-8f2a-80c7e7723462', 'concept'::public.curated_course_node_type, 'Holocaust aftermath', null, 1),
  ('5003c3a2-39b7-4085-8bb9-8713dbdbbd1e', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e31cc552-be42-4560-8f2a-80c7e7723462', 'concept'::public.curated_course_node_type, 'Cold War atmosphere', null, 2),
  ('f11de40b-0004-4018-8d6e-60855fbf687d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e31cc552-be42-4560-8f2a-80c7e7723462', 'concept'::public.curated_course_node_type, 'Alienation', null, 3),
  ('d6946986-46a2-4867-8bbc-5b5ae2d6bf07', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'American Realism and the Broadway/Regional Theater System', 'American realism gives students tools to understand family, capitalism, race, gender, national myth, and psychological struggle on the U.S. stage. This topic also situates canonical playwrights inside Broadway, Off-Broadway, and regional theater institutions.', 7),
  ('d3ca06ae-6051-46e8-8b95-51f0f74b1363', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd6946986-46a2-4867-8bbc-5b5ae2d6bf07', 'subtopic'::public.curated_course_node_type, 'Major dramatists', 'Why learn it: Students study O''Neill, Miller, Williams, Hansberry, and later realist writers as artists of social and psychological conflict.', 0),
  ('e55ccc04-0565-407b-aa34-9ba795faf4da', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd3ca06ae-6051-46e8-8b95-51f0f74b1363', 'concept'::public.curated_course_node_type, 'Eugene O''Neill', null, 0),
  ('332cab3a-3a69-45ce-bc13-3b2e48469f15', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd3ca06ae-6051-46e8-8b95-51f0f74b1363', 'concept'::public.curated_course_node_type, 'Arthur Miller', null, 1),
  ('a4d7bcdc-adac-4e62-95bb-a173535f71e2', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd3ca06ae-6051-46e8-8b95-51f0f74b1363', 'concept'::public.curated_course_node_type, 'Tennessee Williams', null, 2),
  ('2b6e0429-5c8f-421a-82c7-3c7d19ae3985', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd3ca06ae-6051-46e8-8b95-51f0f74b1363', 'concept'::public.curated_course_node_type, 'Lorraine Hansberry', null, 3),
  ('b3b4a6d7-2aba-4ad1-aed2-da14cd60cfdf', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'd6946986-46a2-4867-8bbc-5b5ae2d6bf07', 'subtopic'::public.curated_course_node_type, 'Institutions and audiences', 'Why learn it: Students learn how Broadway commerce, nonprofit regional theater, Off-Broadway, and university theater shape what gets produced.', 1),
  ('4a8119ec-1701-46bb-ba1d-ea1c0f5be56c', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'b3b4a6d7-2aba-4ad1-aed2-da14cd60cfdf', 'concept'::public.curated_course_node_type, 'Broadway economics', null, 0);
