  ('28106d0e-09a3-4b29-9e88-8a62aa62d154', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '0f63e8e0-0383-46cc-96dc-517bbe09f3fd', 'concept'::public.curated_course_node_type, 'Kitchen-sink realism', null, 2),
  ('bb97fdec-16f3-4d2e-a6d4-2762977871e5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '0f63e8e0-0383-46cc-96dc-517bbe09f3fd', 'concept'::public.curated_course_node_type, 'Social problem drama', null, 3),
  ('6ea966ba-4d64-47aa-9ee2-37279ba686aa', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Black Theater, Civil Rights, and Performance of Race', 'A world-class Theater History II must treat Black theater as central, not supplementary. Students study artistic movements, institutions, aesthetics, and political struggles that transformed modern and contemporary theater.', 8),
  ('e5743b15-6412-4774-aa23-239ac1ad62b4', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '6ea966ba-4d64-47aa-9ee2-37279ba686aa', 'subtopic'::public.curated_course_node_type, 'Harlem Renaissance and Black performance institutions', 'Why learn it: Students connect modern Black drama to music, poetry, clubs, publications, and community institutions.', 0),
  ('459cb844-ff16-48ab-8f83-850a361633f0', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e5743b15-6412-4774-aa23-239ac1ad62b4', 'concept'::public.curated_course_node_type, 'Harlem Renaissance', null, 0),
  ('6a35f5ba-6a93-4481-9c93-584272521aef', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'e5743b15-6412-4774-aa23-239ac1ad62b4', 'concept'::public.curated_course_node_type, 'Little theater movement', null, 1),
