  ('420c9530-ff70-4a1e-ad18-49cfef80f9d5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '6ea966ba-4d64-47aa-9ee2-37279ba686aa', 'subtopic'::public.curated_course_node_type, 'Contemporary Black drama', 'Why learn it: Students trace lineage from Hansberry to Wilson, Parks, Nottage, Morisseau, and others.', 2),
  ('30c5f21d-3915-4b6f-9f11-a1c270e6bf09', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '420c9530-ff70-4a1e-ad18-49cfef80f9d5', 'concept'::public.curated_course_node_type, 'August Wilson', null, 0),
