  ('73d17b8a-61cb-4092-a778-5e835cc87659', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '420c9530-ff70-4a1e-ad18-49cfef80f9d5', 'concept'::public.curated_course_node_type, 'Lynn Nottage', null, 2),
  ('bebfb91a-bc0d-48c0-8c57-710b69900800', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '420c9530-ff70-4a1e-ad18-49cfef80f9d5', 'concept'::public.curated_course_node_type, 'Dominique Morisseau', null, 3),
  ('ad98b3fe-507c-460b-8bbe-a62acd373840', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Feminist, Queer, and Disability Theater', 'This topic examines how theater contests the body politics of modernity. Students learn how feminist, queer, trans, and disability performance challenge norms of authorship, representation, spectatorship, access, and institutional power.', 9),
  ('5f7ac559-4434-4a7c-b18e-ef612098cbd9', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'ad98b3fe-507c-460b-8bbe-a62acd373840', 'subtopic'::public.curated_course_node_type, 'Feminist theater histories', 'Why learn it: Students explore consciousness-raising, collective creation, women''s theaters, and feminist revisions of dramatic form.', 0),
  ('eddd980b-c03a-4583-a5f4-7affdb3a8f66', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '5f7ac559-4434-4a7c-b18e-ef612098cbd9', 'concept'::public.curated_course_node_type, 'Caryl Churchill', null, 0),
