  ('1dad628f-c924-423c-9b4b-783acd544db5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '5f7ac559-4434-4a7c-b18e-ef612098cbd9', 'concept'::public.curated_course_node_type, 'Women''s theater companies', null, 2),
