  ('688b2927-2e5b-4bdd-a3d2-59c7102759cc', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'ad98b3fe-507c-460b-8bbe-a62acd373840', 'subtopic'::public.curated_course_node_type, 'Disability performance and access aesthetics', 'Why learn it: Students learn how disability theater changes assumptions about bodies, communication, casting, and design.', 2),
  ('6865e075-cad5-4cb3-8ac9-abd47486d523', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '688b2927-2e5b-4bdd-a3d2-59c7102759cc', 'concept'::public.curated_course_node_type, 'Disability justice', null, 0),
