  ('f9189098-3fa1-4ec2-b615-1a581719609e', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '8b6c19e1-ff5b-4fa6-9022-3e47678952c0', 'subtopic'::public.curated_course_node_type, 'Postmodern form', 'Why learn it: Students identify fragmentation, intertextuality, irony, simultaneity, and unstable meaning.', 0),
  ('f8c3eafc-5ad6-4ed5-882f-69081ec9a370', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'f9189098-3fa1-4ec2-b615-1a581719609e', 'concept'::public.curated_course_node_type, 'Collage', null, 0),
