  ('60e09c62-5544-4776-8352-feb1784e7880', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '3fec9479-654a-4acf-8e24-cc00c405b7c4', 'concept'::public.curated_course_node_type, 'The Wooster Group', null, 0),
