  ('ca138e03-9414-40b6-8b58-63d6614e47e8', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '3fec9479-654a-4acf-8e24-cc00c405b7c4', 'concept'::public.curated_course_node_type, 'Robert Wilson', null, 2),
  ('b5575262-852f-4a98-9e44-40cd76cb3714', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '3fec9479-654a-4acf-8e24-cc00c405b7c4', 'concept'::public.curated_course_node_type, 'Richard Foreman', null, 3),
