  ('7b2a381a-22e4-42e5-aad5-092bd40f106e', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '8cccee8e-518b-49f1-ab33-c1cb940c4241', 'concept'::public.curated_course_node_type, 'Allan Kaprow', null, 0),
