  ('78a394df-699b-4b2e-ad31-952f3c7adaea', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '8cccee8e-518b-49f1-ab33-c1cb940c4241', 'concept'::public.curated_course_node_type, 'Body art', null, 2),
  ('cd13fe3a-8cc8-43c1-a013-5e6e2a712951', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '8cccee8e-518b-49f1-ab33-c1cb940c4241', 'concept'::public.curated_course_node_type, 'Site-specific events', null, 3),
  ('78a8fe65-6503-4b59-910f-2b6c15145d85', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Diverse and Global Theater Voices', 'This section makes global theater voices a major pillar. Students study postcolonial, Indigenous, Latinx, Asian American, African, Middle Eastern, and transnational theater without treating diversity as an add-on.', 11),
  ('2a847b5d-f561-4214-b63b-72ce745e7739', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '78a8fe65-6503-4b59-910f-2b6c15145d85', 'subtopic'::public.curated_course_node_type, 'Postcolonial and decolonial theater', 'Why learn it: Students examine how theater confronts empire, language, nationhood, migration, and cultural survival.', 0),
  ('7c6c6c1a-0201-432f-b62e-294b0841d2fd', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2a847b5d-f561-4214-b63b-72ce745e7739', 'concept'::public.curated_course_node_type, 'Wole Soyinka', null, 0),
