  ('bd7e8e0f-6b7c-4454-84b1-d42ba91fb735', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2a847b5d-f561-4214-b63b-72ce745e7739', 'concept'::public.curated_course_node_type, 'Ngugi wa Thiong''o', null, 2),
  ('0aabc5aa-3772-470a-81e6-3f20e26bbe26', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '2a847b5d-f561-4214-b63b-72ce745e7739', 'concept'::public.curated_course_node_type, 'Decolonial dramaturgy', null, 3),
  ('b289d30b-f0e9-4301-bdf6-4bc3d2e4c78d', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '78a8fe65-6503-4b59-910f-2b6c15145d85', 'subtopic'::public.curated_course_node_type, 'Indigenous and intercultural performance', 'Why learn it: Students learn to distinguish exchange, adaptation, sovereignty, appropriation, and community accountability.', 1),
  ('47d8a419-6ec5-4289-968d-85b46fe90f4b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'b289d30b-f0e9-4301-bdf6-4bc3d2e4c78d', 'concept'::public.curated_course_node_type, 'Indigenous theater', null, 0),
