  ('93136482-94c5-4922-aa0c-0f965770fc4e', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'b289d30b-f0e9-4301-bdf6-4bc3d2e4c78d', 'concept'::public.curated_course_node_type, 'Intercultural ethics', null, 2),
  ('9db5a57e-4460-4947-b025-202cfc3e6976', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'b289d30b-f0e9-4301-bdf6-4bc3d2e4c78d', 'concept'::public.curated_course_node_type, 'Ceremony and performance', null, 3),
  ('43284ccf-84d0-4dda-a2cb-2945d15105b5', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '78a8fe65-6503-4b59-910f-2b6c15145d85', 'subtopic'::public.curated_course_node_type, 'Diasporic and transnational theater', 'Why learn it: Students trace migration, hybridity, multilingual performance, and global production networks.', 2),
  ('2656533c-7614-4ab6-a650-1a43b214be24', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '43284ccf-84d0-4dda-a2cb-2945d15105b5', 'concept'::public.curated_course_node_type, 'Latinx theater', null, 0),
