  ('45917ec6-5006-4da7-b62d-414dfcea82bd', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '43284ccf-84d0-4dda-a2cb-2945d15105b5', 'concept'::public.curated_course_node_type, 'Arab and Middle Eastern theater', null, 2),
  ('b8bfb668-b601-49f1-8428-60c030e9c16b', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '43284ccf-84d0-4dda-a2cb-2945d15105b5', 'concept'::public.curated_course_node_type, 'Translation and touring', null, 3),
  ('14cb1d0b-86ac-400e-a8aa-9fd93a0e6b6f', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Devised, Documentary, and Community-Based Theater', 'Many contemporary artists make theater from interviews, archives, ensemble improvisation, civic partnerships, and lived community experience. Students learn how authorship, evidence, ethics, and process shift in these forms.', 12),
  ('83925617-7fe4-43b4-bb8e-59a555f64076', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '14cb1d0b-86ac-400e-a8aa-9fd93a0e6b6f', 'subtopic'::public.curated_course_node_type, 'Devising methods', 'Why learn it: Students study ensemble-generated performance and the relationship between process and product.', 0),
  ('92c265fb-bf9a-4948-ae35-c683d550f49c', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '83925617-7fe4-43b4-bb8e-59a555f64076', 'concept'::public.curated_course_node_type, 'Improvisation', null, 0),
