  ('67825963-b6af-4af3-9121-d6bab90aab78', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', '14cb1d0b-86ac-400e-a8aa-9fd93a0e6b6f', 'subtopic'::public.curated_course_node_type, 'Documentary and verbatim theater', 'Why learn it: Students learn how interviews, trials, public records, and testimony become performance.', 1),
