  ('ee41f143-e41a-4567-837a-921903c6c4f9', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', null, 'topic'::public.curated_course_node_type, 'Contemporary Theater, Digital Performance, and the Future of the Field', 'The final topic asks students to connect history to the living field. Contemporary theater includes new writing, immersive work, digital platforms, climate dramaturgy, institutional reform, and debates over access, labor, representation, and technology.', 13),
  ('ff7ebaff-8844-48fd-920b-5f6fc79d8726', 'f4a5b6c7-8d9e-4f34-9b34-4c5d6e7f8a34', 'ee41f143-e41a-4567-837a-921903c6c4f9', 'subtopic'::public.curated_course_node_type, 'Contemporary playwriting and production cultures', 'Why learn it: Students identify current theatrical ecosystems, from new-play development to festivals, nonprofit theaters, commercial work, and independent collectives.', 0),
