  'Theater History II',
  'This course surveys theater and performance from the 19th century to the present, tracking realism, modernism, political theater, postwar experimentation, American drama, global and diasporic theater, devised and documentary practices, and contemporary digital and institutional change. Students study plays, manifestos, reviews, production records, video documentation, and theater institutions while asking how modern theater history is shaped by power, preservation, labor, technology, race, gender, sexuality, disability, empire, and audience culture.',
  $thi2json${"slug": "theater-history-ii", "title": "Theater History II", "description": "This course surveys theater and performance from the 19th century to the present, tracking realism, modernism, political theater, postwar experimentation, American drama, global and diasporic theater, devised and documentary practices, and contemporary digital and institutional change. Students study plays, manifestos, reviews, production records, video documentation, and theater institutions while asking how modern theater history is shaped by power, preservation, labor, technology, race, gender, sexuality, disability, empire, and audience culture.", "topics": [{"id": "be97567c-2b28-451e-b5b3-b150f2a74260", "type": "topic", "title": "Modern Theater Historiography and Research Methods", "description": "Theater History II asks students to track a rapidly expanding modern field: industrialization, empire, realism, modernism, mass media, civil rights, feminism, globalization, and digital culture all reshape theater. This opening topic trains students to interpret modern theater through evidence, institutions, and historiographic debate.", "children": [{"id": "4a9ebc4d-da7d-44a2-a173-6d685aa0aaa3", "type": "subtopic", "title": "Modernity and performance evidence", "children": [{"id": "301798e0-6d80-4df0-9558-262454ae43b0", "type": "concept", "title": "Reviews and criticism"}, {"id": "46771f05-ada3-478f-b2fe-c6bb0ea5ad53", "type": "concept", "title": "Production photographs"}, {"id": "b6e78fe7-02f3-4e3b-9fdc-31d535b7feb1", "type": "concept", "title": "Prompt books and programs"}, {"id": "b10b02cf-fc0a-4398-b18a-ea997f6767d7", "type": "concept", "title": "Recorded performance and archives"}], "description": "Why learn it: Students learn how modern theater leaves different traces than earlier theater: photographs, prompt books, reviews, manifestos, video, oral histories, and institutional records."}, {"id": "90de379e-1404-4824-bf05-4b5112421ff8", "type": "subtopic", "title": "Canon revision", "children": [{"id": "5b3b35ac-b820-492f-bb12-cc6f613dfe70", "type": "concept", "title": "Commercial success vs. preservation"}, {"id": "6791f37d-be66-4028-92e1-a569ec5a55d6", "type": "concept", "title": "Translation and circulation"}, {"id": "14ad020c-4a75-4142-8e66-7718587b8024", "type": "concept", "title": "University anthologies"}, {"id": "62d9aced-0061-4c25-89a0-88f5b59fa300", "type": "concept", "title": "Archives and erasure"}], "description": "Why learn it: The point is to ask why some artists became central to theater history while others were excluded by race, gender, class, language, geography, or access to publication."}, {"id": "9a462e06-c8bf-4cca-97f2-afa56ea0ab0c", "type": "subtopic", "title": "Research and citation practice", "children": [{"id": "acd98bb0-306e-4130-8bb4-dcf1bf6cf928", "type": "concept", "title": "Primary/secondary distinction"}, {"id": "29ebd0ec-0476-4883-bd1f-580d24b980bc", "type": "concept", "title": "Annotated bibliography"}, {"id": "3660c544-00c9-4705-9353-f7356e6339fd", "type": "concept", "title": "Oral history ethics"}, {"id": "e81e8db2-a0f3-4ff0-ae6b-89703d6d9682", "type": "concept", "title": "Digital archive literacy"}], "description": "Why learn it: Students build habits for historical argument, source evaluation, and ethical quotation of living or recently living communities."}]}, {"id": "d5d15c1a-c76e-4e0f-8dc8-63621e7e4345", "type": "topic", "title": "Romanticism and Melodrama", "description": "Romanticism and melodrama introduce the 19th century as an age of emotion, spectacle, nationalism, popular entertainment, and changing audiences. Students see how theatrical taste shifts away from neoclassical restraint toward heightened feeling and visual effect.", "children": [{"id": "eea25bb8-cbdb-43d6-b8d0-bfeb894b60df", "type": "subtopic", "title": "Romantic revolt", "children": [{"id": "2a4d559f-a28b-4092-af61-d8674fa75d45", "type": "concept", "title": "Victor Hugo"}, {"id": "aa378372-3db8-41dc-8fe9-e01ed2df51d4", "type": "concept", "title": "Prefaces and manifestos"}, {"id": "bdb85f39-e943-46b2-a719-a0f797bb3e70", "type": "concept", "title": "The grotesque and sublime"}, {"id": "53526a21-ca59-4bdf-942d-17339b192fc3", "type": "concept", "title": "National identity"}], "description": "Why learn it: Students learn how Romantic theater challenged rules of genre, decorum, and classical hierarchy."}, {"id": "20c8309c-66c5-4f1c-bdcc-da5e9a4e8832", "type": "subtopic", "title": "Melodrama as popular form", "children": [{"id": "29ca7404-bf0a-4f06-960b-6c604fd123ec", "type": "concept", "title": "Villains and victims"}, {"id": "2272013e-a018-472b-83a4-491c01444d3f", "type": "concept", "title": "Music underscoring"}, {"id": "a3a2e149-0a61-4f69-a64a-c6997c2fb07d", "type": "concept", "title": "Sensation scenes"}, {"id": "bed637ca-9e71-4d2f-b861-8aa34037e053", "type": "concept", "title": "Moral legibility"}], "description": "Why learn it: Students study melodrama as a major theatrical language of morality, sensation, music, and spectacle."}, {"id": "c001c41c-5e28-4e20-b145-d61d4a1f4eac", "type": "subtopic", "title": "19th-century theater industry", "children": [{"id": "41017f65-cb2a-4151-8b11-2aac77116e28", "type": "concept", "title": "Boulevard theaters"}, {"id": "1ab48a5e-a727-4799-9ccc-e70931c76721", "type": "concept", "title": "Stock companies"}, {"id": "a118771c-09f5-42fe-9d28-fbae36859059", "type": "concept", "title": "Star system"}, {"id": "90838c6a-4b49-405a-8401-b2d23a9bbedd", "type": "concept", "title": "Gaslight and scenic effects"}], "description": "Why learn it: Students connect dramatic form to urbanization, touring, star actors, patents, censorship, and commercial management."}]}, {"id": "414db79d-3dc8-40ba-82fd-5fbda3d68ace", "type": "topic", "title": "Realism and Naturalism", "description": "Realism and naturalism reshape modern drama by putting ordinary life, social systems, psychology, and environment at the center of theatrical representation. Students learn why this shift became foundational for modern acting, directing, design, and dramaturgy.", "children": [{"id": "37de8cba-77b4-4254-b221-7c76d78d1bf3", "type": "subtopic", "title": "Realist dramaturgy", "children": [{"id": "3a702f18-4e1c-4dbd-9f32-59893a63dc84", "type": "concept", "title": "Henrik Ibsen"}, {"id": "fdbf8563-4fae-43be-b6bd-1dd953fc7f54", "type": "concept", "title": "Anton Chekhov"}, {"id": "2640ee31-ebd4-404c-8187-8c5aa2acfbfd", "type": "concept", "title": "The well-made play"}, {"id": "cda82396-ffd2-4565-9966-698ca7f2630d", "type": "concept", "title": "Subtext and silence"}], "description": "Why learn it: Students analyze how subtext, social conflict, prose dialogue, and domestic settings produce modern dramatic tension."}, {"id": "c815f1b8-227f-4691-84ea-ce7b7569f2f5", "type": "subtopic", "title": "Naturalism and environment", "children": [{"id": "7eeba159-5883-428d-a363-02faea6caa8c", "type": "concept", "title": "Emile Zola"}, {"id": "5c189796-e30f-4c44-84e2-935837306aa4", "type": "concept", "title": "Andre Antoine"}, {"id": "eab42eb5-bc40-4cdf-a7fa-fcc563b7ce67", "type": "concept", "title": "Fourth wall"}, {"id": "ba081c2a-3fb3-4b9e-8fc4-5f7c898b8460", "type": "concept", "title": "Detailed scenic realism"}], "description": "Why learn it: Students learn how heredity, class, labor, and material conditions become dramatic forces."}, {"id": "22e21c09-4730-4893-ad64-381af5f9de07", "type": "subtopic", "title": "Modern acting and directing", "children": [{"id": "6a5b81a3-0d23-4361-8743-360ebf1c2eff", "type": "concept", "title": "Stanislavski"}, {"id": "e181ffc3-6fcc-45fd-abe6-11c3cb63874a", "type": "concept", "title": "Moscow Art Theatre"}, {"id": "a3346be9-3819-4354-9b07-2b6546ac6727", "type": "concept", "title": "Ensemble practice"}, {"id": "d979fbd2-fc48-4b33-bf10-569813060ffb", "type": "concept", "title": "Given circumstances"}], "description": "Why learn it: Students connect realism to ensemble rehearsal, psychological acting, and the rise of the director."}]}, {"id": "27021253-30dd-4d0d-82f8-0ff0d8aa152c", "type": "topic", "title": "Symbolism and the Avant-Garde", "description": "Symbolism and the avant-garde show artists rejecting literal realism in favor of dream, ritual, abstraction, manifesto, shock, and anti-bourgeois experiment. Students learn that modern theater develops through competing ideas of truth.", "children": [{"id": "7652c268-05e5-4ea6-97a5-bc93d7d3d3d4", "type": "subtopic", "title": "Symbolist theater", "children": [{"id": "d3d4ffdb-e8be-4278-b78c-8e74ffdb4585", "type": "concept", "title": "Maeterlinck"}, {"id": "c76dadc5-194b-4ade-8190-47c23c6d8ec4", "type": "concept", "title": "Mallarme"}, {"id": "2a4c2836-fccd-495b-a071-d3fc5cc199e8", "type": "concept", "title": "Dream logic"}, {"id": "2425b3fd-79c3-44f0-b54a-49cc0ed86df2", "type": "concept", "title": "Anti-naturalist staging"}], "description": "Why learn it: Students examine atmosphere, suggestion, music, color, and spiritual mystery as alternatives to realist detail."}, {"id": "60745087-f001-4e99-87ca-fdb7f2f90580", "type": "subtopic", "title": "Futurism, Dada, and Surrealism", "children": [{"id": "4f688539-fc0a-494c-bcaa-699055ecbe19", "type": "concept", "title": "Marinetti"}, {"id": "78937b28-46a7-477a-bfc9-4e8e75b15a6b", "type": "concept", "title": "Cabaret Voltaire"}, {"id": "bdfefb57-84f9-4cd8-8fad-4693785eac3b", "type": "concept", "title": "Automatic writing"}, {"id": "bc7e331d-0283-4d46-93a6-3b101d54cc63", "type": "concept", "title": "Manifesto performance"}], "description": "Why learn it: Students study performance as provocation, speed, collage, nonsense, anti-war protest, and unconscious expression."}, {"id": "9ea2835f-7883-4a1d-bd5d-1411b04a5c8b", "type": "subtopic", "title": "Avant-garde scenography", "children": [{"id": "94141730-c1bf-4d42-b71a-ef33a02d0fa2", "type": "concept", "title": "Adolphe Appia"}, {"id": "8dfb22f0-8ab9-4f8e-91c0-d2de75b8ba85", "type": "concept", "title": "Edward Gordon Craig"}, {"id": "9936b526-7c48-40f4-a317-e4cbc8fc4580", "type": "concept", "title": "Plastic space"}, {"id": "2252dd08-5b6b-45bf-b662-5f810144df5d", "type": "concept", "title": "Performer as image"}], "description": "Why learn it: Students connect visual abstraction to new theories of stage space, light, movement, and audience perception."}]}, {"id": "92226173-7d3c-4861-892a-447e397361f6", "type": "topic", "title": "Expressionism", "description": "Expressionism turns theater inward and outward at once: distorted worlds reveal psychic crisis, social alienation, industrial pressure, and political anxiety. Students learn how form can stage subjective experience.", "children": [{"id": "08d65372-125d-4510-9d53-9e8c39366840", "type": "subtopic", "title": "Expressionist dramaturgy", "children": [{"id": "b07a7ff9-3bca-430b-8d98-7aef004b651e", "type": "concept", "title": "Stationsdrama"}, {"id": "30181fdf-f341-4dba-8ee0-68f6e37f3d89", "type": "concept", "title": "Archetypes"}, {"id": "52f1d118-b9cd-454c-91b7-dc4986f1d2d2", "type": "concept", "title": "Monologue and outcry"}, {"id": "bcb3695a-ba3e-48cb-8de0-8849b26994f1", "type": "concept", "title": "Fragmented scenes"}], "description": "Why learn it: Students identify episodic structure, archetypal characters, distorted dialogue, and nightmare logic."}, {"id": "9db1e1fd-197e-4eb9-a35a-7869beb717d3", "type": "subtopic", "title": "Design and performance style", "children": [{"id": "c5b568aa-1abb-4f91-936f-3fafe054569b", "type": "concept", "title": "Distortion"}, {"id": "f4f78a55-7262-441b-9383-40cee82ae159", "type": "concept", "title": "Chiaroscuro"}, {"id": "f59e801e-b2e5-4c60-b2b9-e292b379f61b", "type": "concept", "title": "Stylized movement"}, {"id": "495552eb-e35d-43e6-9a99-a90ecb6d79bf", "type": "concept", "title": "Anti-realistic sound"}], "description": "Why learn it: Students learn how light, shadow, gesture, makeup, sound, and angular space externalize inner states."}, {"id": "ad0850a8-75fa-4209-a372-d5c413ca09e1", "type": "subtopic", "title": "Social critique", "children": [{"id": "6a3b86f1-7358-4183-8a22-b476b9ce9112", "type": "concept", "title": "Georg Kaiser"}, {"id": "7b160e1b-ee6d-42f3-ba46-63a6e6eef28d", "type": "concept", "title": "Ernst Toller"}, {"id": "e5960b60-eb1f-422f-9e21-92cde4e450e5", "type": "concept", "title": "Machine age"}, {"id": "5192e0b7-fa2f-4b7b-a0a8-07070f02b897", "type": "concept", "title": "Anti-war drama"}], "description": "Why learn it: Students connect expressionism to war, industrial labor, bureaucracy, family power, and modern alienation."}]}, {"id": "0865b672-2553-4cf1-a98e-0620da4da621", "type": "topic", "title": "Epic Theater and Brecht", "description": "Epic theater asks students to understand theater as a tool for historical analysis rather than emotional absorption alone. Brecht becomes a gateway into politics, spectatorship, performance theory, and anti-illusionist staging.", "children": [{"id": "1ebd285d-2f8c-4916-94cd-e14bb84b2b87", "type": "subtopic", "title": "Alienation and critical spectatorship", "children": [{"id": "3f7031d4-48f8-4cf2-bbe8-9bd6a599b62d", "type": "concept", "title": "Verfremdungseffekt"}, {"id": "27fcdf83-7de9-4ed0-b422-b4593cc546bd", "type": "concept", "title": "Direct address"}, {"id": "43c3312c-1bb9-4158-981b-6241840cd2eb", "type": "concept", "title": "Placards"}, {"id": "ab49b400-ea47-49af-bfc0-11e9f60cfae3", "type": "concept", "title": "Visible mechanics"}], "description": "Why learn it: Students learn how theater can interrupt identification and invite analysis."}, {"id": "e2acae15-200f-4739-8cc5-74e64ec1e982", "type": "subtopic", "title": "Historification and dialectics", "children": [{"id": "f8aa2466-7d7d-467f-9aff-afbd04bb7800", "type": "concept", "title": "Gestus"}, {"id": "c817dc09-feef-49eb-be3b-2bd892e8ff34", "type": "concept", "title": "Contradiction"}, {"id": "f256a14b-fbbf-42b7-871f-eaf004cd6e39", "type": "concept", "title": "Scene titles"}, {"id": "f96652a8-b169-45a1-97d0-d584dc43ee89", "type": "concept", "title": "Narrative interruption"}], "description": "Why learn it: Students study how epic theater frames social arrangements as changeable rather than natural."}, {"id": "e6d0e77e-43c8-4c78-ba14-1cc46103e276", "type": "subtopic", "title": "Brechtian legacy", "children": [{"id": "e960da43-6d37-4cfd-8113-a7b38d60ffc5", "type": "concept", "title": "Mother Courage"}, {"id": "be3abce9-28ca-4ec7-a374-a8d0816c4ce0", "type": "concept", "title": "The Good Person of Szechwan"}, {"id": "d98d3953-b5b3-436e-aa1e-7299199c115b", "type": "concept", "title": "Political cabaret"}, {"id": "7d2bd3f5-8bc9-487b-b579-8b850f9fecba", "type": "concept", "title": "Documentary forms"}], "description": "Why learn it: Students trace epic techniques into documentary theater, political theater, devised performance, and contemporary staging."}]}, {"id": "f5c99ffb-d78a-4758-be1d-e658bea3fb78", "type": "topic", "title": "Absurdism and Postwar Theater", "description": "Absurdism responds to war, existential crisis, fractured communication, and the collapse of stable meaning. Students learn how repetition, silence, circular action, and comic despair create a postwar theatrical language.", "children": [{"id": "07aef9b6-6641-413f-b414-a797d4543f95", "type": "subtopic", "title": "Theater of the Absurd", "children": [{"id": "229d07e4-96c2-4182-9245-38d77f1a4c13", "type": "concept", "title": "Samuel Beckett"}, {"id": "f113fcde-477b-48ea-8980-f65c4bfcb892", "type": "concept", "title": "Eugene Ionesco"}, {"id": "2600e0e8-01a0-4dde-aa2d-86679d72b79c", "type": "concept", "title": "Jean Genet"}, {"id": "6950b4c7-5bc5-421f-8c4b-c4c40e3a9d11", "type": "concept", "title": "Circular structure"}], "description": "Why learn it: Students analyze how Beckett, Ionesco, Genet, and others challenge plot, character, language, and certainty."}, {"id": "2f6e0b7f-57a8-4177-b209-5c8bee7834a9", "type": "subtopic", "title": "Language breakdown", "children": [{"id": "9ec65fc3-a44a-46e1-b3b3-fc3846584210", "type": "concept", "title": "Cliche"}, {"id": "692322b5-5c64-45fc-b845-cafa29afa5d2", "type": "concept", "title": "Repetition"}, {"id": "321b595a-0fcf-48db-a6c6-e1150972b7c6", "type": "concept", "title": "Silence"}, {"id": "39a4fd37-d5fb-4d7f-b561-2a834d3ac329", "type": "concept", "title": "Nonsense logic"}], "description": "Why learn it: Students learn how failed communication becomes dramatic action."}, {"id": "e31cc552-be42-4560-8f2a-80c7e7723462", "type": "subtopic", "title": "Postwar context", "children": [{"id": "b77d7f63-2463-499f-a147-a7291b23800e", "type": "concept", "title": "Existential philosophy"}, {"id": "fa596d04-b434-4c2d-b0f1-95676924b089", "type": "concept", "title": "Holocaust aftermath"}, {"id": "5003c3a2-39b7-4085-8bb9-8713dbdbbd1e", "type": "concept", "title": "Cold War atmosphere"}, {"id": "f11de40b-0004-4018-8d6e-60855fbf687d", "type": "concept", "title": "Alienation"}], "description": "Why learn it: Students connect absurdism to World War II, existentialism, displacement, bureaucracy, and modern anxiety."}]}, {"id": "d6946986-46a2-4867-8bbc-5b5ae2d6bf07", "type": "topic", "title": "American Realism and the Broadway/Regional Theater System", "description": "American realism gives students tools to understand family, capitalism, race, gender, national myth, and psychological struggle on the U.S. stage. This topic also situates canonical playwrights inside Broadway, Off-Broadway, and regional theater institutions.", "children": [{"id": "d3ca06ae-6051-46e8-8b95-51f0f74b1363", "type": "subtopic", "title": "Major dramatists", "children": [{"id": "e55ccc04-0565-407b-aa34-9ba795faf4da", "type": "concept", "title": "Eugene O'Neill"}, {"id": "332cab3a-3a69-45ce-bc13-3b2e48469f15", "type": "concept", "title": "Arthur Miller"}, {"id": "a4d7bcdc-adac-4e62-95bb-a173535f71e2", "type": "concept", "title": "Tennessee Williams"}, {"id": "2b6e0429-5c8f-421a-82c7-3c7d19ae3985", "type": "concept", "title": "Lorraine Hansberry"}], "description": "Why learn it: Students study O'Neill, Miller, Williams, Hansberry, and later realist writers as artists of social and psychological conflict."}, {"id": "b3b4a6d7-2aba-4ad1-aed2-da14cd60cfdf", "type": "subtopic", "title": "Institutions and audiences", "children": [{"id": "4a8119ec-1701-46bb-ba1d-ea1c0f5be56c", "type": "concept", "title": "Broadway economics"}, {"id": "54768a96-6839-46e0-bf24-5edd8a6276a8", "type": "concept", "title": "Off-Broadway"}, {"id": "5838b1f0-5c6d-4025-a36e-3bab3fc8b52b", "type": "concept", "title": "Regional theaters"}, {"id": "132aceb8-d89d-4ed0-b0a2-0cf3e10ae773", "type": "concept", "title": "Subscription audiences"}], "description": "Why learn it: Students learn how Broadway commerce, nonprofit regional theater, Off-Broadway, and university theater shape what gets produced."}, {"id": "0f63e8e0-0383-46cc-96dc-517bbe09f3fd", "type": "subtopic", "title": "Realism under pressure", "children": [{"id": "b4d96314-9283-4d83-b503-8fe57fbfa3b5", "type": "concept", "title": "Memory plays"}, {"id": "3e74c801-61fc-40db-87fe-855830908d35", "type": "concept", "title": "Expressionistic realism"}, {"id": "28106d0e-09a3-4b29-9e88-8a62aa62d154", "type": "concept", "title": "Kitchen-sink realism"}, {"id": "bb97fdec-16f3-4d2e-a6d4-2762977871e5", "type": "concept", "title": "Social problem drama"}], "description": "Why learn it: Students examine how American realism absorbs memory, expressionism, race critique, and poetic language."}]}, {"id": "6ea966ba-4d64-47aa-9ee2-37279ba686aa", "type": "topic", "title": "Black Theater, Civil Rights, and Performance of Race", "description": "A world-class Theater History II must treat Black theater as central, not supplementary. Students study artistic movements, institutions, aesthetics, and political struggles that transformed modern and contemporary theater.", "children": [{"id": "e5743b15-6412-4774-aa23-239ac1ad62b4", "type": "subtopic", "title": "Harlem Renaissance and Black performance institutions", "children": [{"id": "459cb844-ff16-48ab-8f83-850a361633f0", "type": "concept", "title": "Harlem Renaissance"}, {"id": "6a35f5ba-6a93-4481-9c93-584272521aef", "type": "concept", "title": "Little theater movement"}, {"id": "7e19159b-eb46-48dd-8f84-c9f61edba085", "type": "concept", "title": "Federal Theatre Project"}, {"id": "ad2d6acb-4c66-419c-a538-a7430d990fea", "type": "concept", "title": "Black musical theater"}], "description": "Why learn it: Students connect modern Black drama to music, poetry, clubs, publications, and community institutions."}, {"id": "f686ee83-a90c-4d1a-8f8a-8dcacea5f487", "type": "subtopic", "title": "Civil Rights and Black Arts Movement", "children": [{"id": "4cc6a49f-8f00-4de1-a6d8-3e6a78204f49", "type": "concept", "title": "Amiri Baraka"}, {"id": "a7624b9d-8af4-4749-af94-8f2ab325ae2d", "type": "concept", "title": "Black Arts Movement"}, {"id": "86bfc352-6704-4faa-bd55-f66012fae18f", "type": "concept", "title": "Community theater"}, {"id": "e44fa084-e35e-4e26-8e21-29c1f7d35368", "type": "concept", "title": "Revolutionary aesthetics"}], "description": "Why learn it: Students study theater as cultural self-definition, protest, and aesthetic revolution."}, {"id": "420c9530-ff70-4a1e-ad18-49cfef80f9d5", "type": "subtopic", "title": "Contemporary Black drama", "children": [{"id": "30c5f21d-3915-4b6f-9f11-a1c270e6bf09", "type": "concept", "title": "August Wilson"}, {"id": "f471de12-5e20-44f6-8e58-c4786c63bd3b", "type": "concept", "title": "Suzan-Lori Parks"}, {"id": "73d17b8a-61cb-4092-a778-5e835cc87659", "type": "concept", "title": "Lynn Nottage"}, {"id": "bebfb91a-bc0d-48c0-8c57-710b69900800", "type": "concept", "title": "Dominique Morisseau"}], "description": "Why learn it: Students trace lineage from Hansberry to Wilson, Parks, Nottage, Morisseau, and others."}]}, {"id": "ad98b3fe-507c-460b-8bbe-a62acd373840", "type": "topic", "title": "Feminist, Queer, and Disability Theater", "description": "This topic examines how theater contests the body politics of modernity. Students learn how feminist, queer, trans, and disability performance challenge norms of authorship, representation, spectatorship, access, and institutional power.", "children": [{"id": "5f7ac559-4434-4a7c-b18e-ef612098cbd9", "type": "subtopic", "title": "Feminist theater histories", "children": [{"id": "eddd980b-c03a-4583-a5f4-7affdb3a8f66", "type": "concept", "title": "Caryl Churchill"}, {"id": "2e0858dc-e8a1-43db-9de9-e2ca2bdc89ac", "type": "concept", "title": "For colored girls"}, {"id": "1dad628f-c924-423c-9b4b-783acd544db5", "type": "concept", "title": "Women's theater companies"}, {"id": "222907dc-e56a-4801-9d22-95224781b94a", "type": "concept", "title": "Collective process"}], "description": "Why learn it: Students explore consciousness-raising, collective creation, women's theaters, and feminist revisions of dramatic form."}, {"id": "b481c4ea-0154-4281-9c77-f706d878aae0", "type": "subtopic", "title": "Queer theater and performance", "children": [{"id": "33c6b753-eede-4de3-845a-5f6ed3833313", "type": "concept", "title": "The Boys in the Band"}, {"id": "a7cd6a6a-c068-44e4-9bd2-07642cd6ad94", "type": "concept", "title": "Angels in America"}, {"id": "36e999a9-5715-42eb-b28b-ed324f312a34", "type": "concept", "title": "Split Britches"}, {"id": "bce47190-421b-4962-800b-f5974d047eac", "type": "concept", "title": "Drag performance"}], "description": "Why learn it: Students study theatrical responses to identity, desire, censorship, HIV/AIDS, chosen family, and public memory."}, {"id": "688b2927-2e5b-4bdd-a3d2-59c7102759cc", "type": "subtopic", "title": "Disability performance and access aesthetics", "children": [{"id": "6865e075-cad5-4cb3-8ac9-abd47486d523", "type": "concept", "title": "Disability justice"}, {"id": "dfbf836c-edd4-4d03-baa3-45be73904f65", "type": "concept", "title": "Integrated access"}, {"id": "c977e04d-cb51-4e81-8a22-f689ee16d515", "type": "concept", "title": "Deaf theater"}, {"id": "affdb831-2054-495e-a9fa-1332d782a820", "type": "concept", "title": "Crip aesthetics"}], "description": "Why learn it: Students learn how disability theater changes assumptions about bodies, communication, casting, and design."}]}, {"id": "8b6c19e1-ff5b-4fa6-9022-3e47678952c0", "type": "topic", "title": "Postmodern and Experimental Theater", "description": "Postmodern and experimental theater breaks open narrative, authorship, character, space, and audience relationship. Students learn how performance can become collage, event, image, process, and critique.", "children": [{"id": "f9189098-3fa1-4ec2-b615-1a581719609e", "type": "subtopic", "title": "Postmodern form", "children": [{"id": "f8c3eafc-5ad6-4ed5-882f-69081ec9a370", "type": "concept", "title": "Collage"}, {"id": "6af1515b-e233-4a78-a939-980d6b55c764", "type": "concept", "title": "Pastiche"}, {"id": "a585fa72-dab9-4726-9b02-39323b6f8799", "type": "concept", "title": "Nonlinear structure"}, {"id": "513779f4-4c5b-44d5-9af0-f47b955a8c17", "type": "concept", "title": "Metatheater"}], "description": "Why learn it: Students identify fragmentation, intertextuality, irony, simultaneity, and unstable meaning."}, {"id": "3fec9479-654a-4acf-8e24-cc00c405b7c4", "type": "subtopic", "title": "Experimental companies and directors", "children": [{"id": "60e09c62-5544-4776-8352-feb1784e7880", "type": "concept", "title": "The Wooster Group"}, {"id": "0db88c6d-0946-4cc4-af8f-376b297d0b01", "type": "concept", "title": "Mabou Mines"}, {"id": "ca138e03-9414-40b6-8b58-63d6614e47e8", "type": "concept", "title": "Robert Wilson"}, {"id": "b5575262-852f-4a98-9e44-40cd76cb3714", "type": "concept", "title": "Richard Foreman"}], "description": "Why learn it: Students study ensemble laboratories and director-led aesthetics that changed late-20th-century staging."}, {"id": "8cccee8e-518b-49f1-ab33-c1cb940c4241", "type": "subtopic", "title": "Performance art and happenings", "children": [{"id": "7b2a381a-22e4-42e5-aad5-092bd40f106e", "type": "concept", "title": "Allan Kaprow"}, {"id": "f5937aa0-cc04-45b5-af39-07980135d235", "type": "concept", "title": "Marina Abramovic"}, {"id": "78a394df-699b-4b2e-ad31-952f3c7adaea", "type": "concept", "title": "Body art"}, {"id": "cd13fe3a-8cc8-43c1-a013-5e6e2a712951", "type": "concept", "title": "Site-specific events"}], "description": "Why learn it: Students connect theater to visual art, body art, public action, and anti-institutional performance."}]}, {"id": "78a8fe65-6503-4b59-910f-2b6c15145d85", "type": "topic", "title": "Diverse and Global Theater Voices", "description": "This section makes global theater voices a major pillar. Students study postcolonial, Indigenous, Latinx, Asian American, African, Middle Eastern, and transnational theater without treating diversity as an add-on.", "children": [{"id": "2a847b5d-f561-4214-b63b-72ce745e7739", "type": "subtopic", "title": "Postcolonial and decolonial theater", "children": [{"id": "7c6c6c1a-0201-432f-b62e-294b0841d2fd", "type": "concept", "title": "Wole Soyinka"}, {"id": "253b6f90-904f-4592-bfa1-6de4d3d21761", "type": "concept", "title": "Athol Fugard"}, {"id": "bd7e8e0f-6b7c-4454-84b1-d42ba91fb735", "type": "concept", "title": "Ngugi wa Thiong'o"}, {"id": "0aabc5aa-3772-470a-81e6-3f20e26bbe26", "type": "concept", "title": "Decolonial dramaturgy"}], "description": "Why learn it: Students examine how theater confronts empire, language, nationhood, migration, and cultural survival."}, {"id": "b289d30b-f0e9-4301-bdf6-4bc3d2e4c78d", "type": "subtopic", "title": "Indigenous and intercultural performance", "children": [{"id": "47d8a419-6ec5-4289-968d-85b46fe90f4b", "type": "concept", "title": "Indigenous theater"}, {"id": "3b2d645d-4876-45f1-ad49-9de0bfe8eb73", "type": "concept", "title": "Sovereignty"}, {"id": "93136482-94c5-4922-aa0c-0f965770fc4e", "type": "concept", "title": "Intercultural ethics"}, {"id": "9db5a57e-4460-4947-b025-202cfc3e6976", "type": "concept", "title": "Ceremony and performance"}], "description": "Why learn it: Students learn to distinguish exchange, adaptation, sovereignty, appropriation, and community accountability."}, {"id": "43284ccf-84d0-4dda-a2cb-2945d15105b5", "type": "subtopic", "title": "Diasporic and transnational theater", "children": [{"id": "2656533c-7614-4ab6-a650-1a43b214be24", "type": "concept", "title": "Latinx theater"}, {"id": "580b8846-f255-4c69-b703-84bcf9f1d589", "type": "concept", "title": "Asian American theater"}, {"id": "45917ec6-5006-4da7-b62d-414dfcea82bd", "type": "concept", "title": "Arab and Middle Eastern theater"}, {"id": "b8bfb668-b601-49f1-8428-60c030e9c16b", "type": "concept", "title": "Translation and touring"}], "description": "Why learn it: Students trace migration, hybridity, multilingual performance, and global production networks."}]}, {"id": "14cb1d0b-86ac-400e-a8aa-9fd93a0e6b6f", "type": "topic", "title": "Devised, Documentary, and Community-Based Theater", "description": "Many contemporary artists make theater from interviews, archives, ensemble improvisation, civic partnerships, and lived community experience. Students learn how authorship, evidence, ethics, and process shift in these forms.", "children": [{"id": "83925617-7fe4-43b4-bb8e-59a555f64076", "type": "subtopic", "title": "Devising methods", "children": [{"id": "92c265fb-bf9a-4948-ae35-c683d550f49c", "type": "concept", "title": "Improvisation"}, {"id": "d0b4fae0-3cb7-42ed-883a-8338dd72d36f", "type": "concept", "title": "Composition"}, {"id": "c5e9c0db-a655-4052-a5b5-80d9fdb45915", "type": "concept", "title": "Viewpoints"}, {"id": "c5d44cfc-c917-4f41-999b-ba7ce3e650fe", "type": "concept", "title": "Collective authorship"}], "description": "Why learn it: Students study ensemble-generated performance and the relationship between process and product."}, {"id": "67825963-b6af-4af3-9121-d6bab90aab78", "type": "subtopic", "title": "Documentary and verbatim theater", "children": [{"id": "d799e8c7-dd9d-46c2-9ab0-516b9a64e3e9", "type": "concept", "title": "Anna Deavere Smith"}, {"id": "33aac42a-8c2a-4fa9-a7e8-59cdf00ca783", "type": "concept", "title": "The Laramie Project"}, {"id": "54149950-c01c-4c05-afcf-9c2961bbf34b", "type": "concept", "title": "Verbatim ethics"}, {"id": "7c2efbb4-eca0-4d1b-97a4-150883bab712", "type": "concept", "title": "Editing testimony"}], "description": "Why learn it: Students learn how interviews, trials, public records, and testimony become performance."}, {"id": "0bcae361-c87b-43f0-aef9-e0c92ff671c6", "type": "subtopic", "title": "Applied and community-based theater", "children": [{"id": "ad4a3bc7-36b3-4ad7-8662-269cd2c8662b", "type": "concept", "title": "Theater of the Oppressed"}, {"id": "f8e14df3-5bb5-41c1-90c2-22d909d43b6d", "type": "concept", "title": "Playback theater"}, {"id": "463510f0-45ae-4152-887f-ca8a8d1d935c", "type": "concept", "title": "Community partnership"}, {"id": "6d91c7dd-2a93-4240-a5f8-54c19d606544", "type": "concept", "title": "Facilitation ethics"}], "description": "Why learn it: Students examine theater in education, prisons, health, activism, and local civic practice."}]}, {"id": "ee41f143-e41a-4567-837a-921903c6c4f9", "type": "topic", "title": "Contemporary Theater, Digital Performance, and the Future of the Field", "description": "The final topic asks students to connect history to the living field. Contemporary theater includes new writing, immersive work, digital platforms, climate dramaturgy, institutional reform, and debates over access, labor, representation, and technology.", "children": [{"id": "ff7ebaff-8844-48fd-920b-5f6fc79d8726", "type": "subtopic", "title": "Contemporary playwriting and production cultures", "children": [{"id": "b5dcd544-3e24-49f6-8894-4463cde26b34", "type": "concept", "title": "New-play development"}, {"id": "8d609d09-35b3-4e22-92b6-47bd0438feb4", "type": "concept", "title": "Festivals"}, {"id": "3ca4c626-af05-4292-835c-30c964383406", "type": "concept", "title": "Nonprofit models"}, {"id": "05a5eb73-87cd-4beb-86e1-5c57ba923ef5", "type": "concept", "title": "Commercial transfer"}], "description": "Why learn it: Students identify current theatrical ecosystems, from new-play development to festivals, nonprofit theaters, commercial work, and independent collectives."}, {"id": "b1a6e27c-9d07-4f1b-8577-ead17b811379", "type": "subtopic", "title": "Digital and immersive performance", "children": [{"id": "71672ae2-e7e3-4a92-a523-a5ed8f0e382e", "type": "concept", "title": "Livestream theater"}, {"id": "69e732a7-8437-4135-97c2-423f4d3b812b", "type": "concept", "title": "Immersive performance"}, {"id": "afe956be-82c4-4660-9a99-488d6b5002c5", "type": "concept", "title": "Transmedia dramaturgy"}, {"id": "ce1614dc-1f5f-4e1c-bec0-fb639be3fe94", "type": "concept", "title": "Interactive audiences"}], "description": "Why learn it: Students examine how media, livestreaming, game structures, virtual reality, and immersive design change spectatorship."}, {"id": "26709c5f-a27a-4617-8242-8550010fae6c", "type": "subtopic", "title": "Institutional futures", "children": [{"id": "9d5c191f-31a8-44b8-932e-32b0fd448c82", "type": "concept", "title": "Climate dramaturgy"}, {"id": "cd8fd5f7-cc2a-4dda-8bb4-d32473f6618b", "type": "concept", "title": "Pay equity"}, {"id": "49a5ed46-7ec6-4a20-9275-0eff9960c78b", "type": "concept", "title": "Anti-racist institutions"}, {"id": "cfc4d100-3855-4200-8e17-a0e18549baa8", "type": "concept", "title": "Audience access"}], "description": "Why learn it: Students evaluate contemporary debates around access, labor, climate, representation, audience development, and public funding."}]}], "dbBacked": true}$thi2json$::jsonb,
